(()=>{const file=document.getElementById('avatar-file'),preview=document.getElementById('avatar-preview'),placeholder=document.getElementById('avatar-placeholder'),save=document.getElementById('avatar-save'),cancel=document.getElementById('avatar-cancel'),remove=document.getElementById('avatar-remove'),status=document.getElementById('avatar-status');let pending=null,current=null,busy=false,selection=0;
function say(t){status.textContent=t}function show(url){preview.hidden=!url;placeholder.hidden=!!url;if(url)preview.src=url;else preview.removeAttribute('src')}function controls(){save.hidden=cancel.hidden=!pending;save.disabled=cancel.disabled=file.disabled=remove.disabled=busy;remove.hidden=!current}
window.loadMemberAvatar=member=>{selection++;pending=null;current=member.avatarUrl||null;file.value='';placeholder.textContent=member.name.slice(0,1);show(current);say('');controls()};
file.addEventListener('change',async()=>{const f=file.files[0],version=++selection;pending=null;show(current);controls();if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)){say('請選擇 JPG、PNG 或 WebP 圖片。');file.value='';return}if(f.size>5*1024*1024){say('照片需小於 5 MB，請選擇較小的圖片。');file.value='';return}say('正在準備照片…');try{const bitmap=await createImageBitmap(f,{imageOrientation:'from-image'});if(version!==selection){bitmap.close();return}if(Math.min(bitmap.width,bitmap.height)<32){bitmap.close();throw Error('照片尺寸太小，請使用至少 32 × 32 像素的圖片。')}const canvas=document.createElement('canvas');canvas.width=canvas.height=512;const ctx=canvas.getContext('2d');ctx.fillStyle='#f4f1e8';ctx.fillRect(0,0,512,512);const side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,512,512);bitmap.close();pending=canvas.toDataURL('image/jpeg',.88);show(pending);say('照片預覽已就緒，按「儲存大頭照」即可上傳。');controls()}catch(e){if(version===selection){say(e.message||'照片讀取失敗，請換一張圖片。');file.value='';controls()}}});
cancel.onclick=()=>{selection++;pending=null;file.value='';show(current);say('已取消更換。');controls()};save.onclick=async()=>{if(!pending||busy)return;busy=true;controls();say('照片上傳中…');try{const r=await WildRideMember.request('avatar',{image:pending});current=r.avatarUrl;WildRideMember.member.avatarUrl=current;pending=null;file.value='';show(current);say('大頭照已儲存。')}catch(e){say(e.message)}finally{busy=false;controls()}};
remove.onclick=async()=>{if(busy||!current)return;busy=true;controls();try{const r=await WildRideMember.request('avatar',{remove:true});current=r.avatarUrl;WildRideMember.member.avatarUrl=current;pending=null;file.value='';show(null);say('已移除大頭照。')}catch(e){say(e.message)}finally{busy=false;controls()}};
})();
